-- pixelrp: every page under Builders > Builders Club wears an icon of its
-- own furni, and Roomad wears the purple Ads MPU.
--
-- Catalog page icons are c_images/catalogue/icon_<n>.png, and the stock set
-- has nothing for a cone, a brick block or a letter. So page icons are made
-- from furni icons, fitted to the 18x18 the stock ones are, and named after
-- the furni's sprite: icon_<7000000 + sprite>.png, under
-- nitro/overrides/c_images/catalogue/ (2453 of them - every Builders Club and
-- Construction furni, and ads_mpu_720).
--
-- A page's icon is its first furni by item name - colour *1 of a set, or the
-- plain Construction piece where there is one - so it is live, not guessed
-- from a file: Builders Club's own pages exist in no migration. A page with
-- no furni of its own (Shapes, Materials) takes its first sub-page's icon.
-- A page whose furni has no icon made keeps the one it has; dividers are left
-- alone, and so is Builders Club itself.
--
-- Roomad (946000) wears ads_mpu_720, the purple one. Idempotent.

SET @builders := (SELECT `id` FROM `catalog_pages` WHERE `parent_id` = -1 AND `caption` = 'Builders' LIMIT 1);
SET @bc := (SELECT `id` FROM `catalog_pages` WHERE `parent_id` = @builders AND `caption` = 'Builders Club' ORDER BY `id` LIMIT 1);

DROP TABLE IF EXISTS `_pi_sprite`;
CREATE TABLE `_pi_sprite` (`sprite_id` INT NOT NULL PRIMARY KEY) ENGINE=InnoDB;
