DELETE s FROM `_pi_pages` s JOIN `catalog_pages` p ON p.`id` = s.`id` WHERE p.`page_link` = 'divider';

-- Pages with furni: the icon of the first by item name that has one made.
DROP TABLE IF EXISTS `_pi_first`;
CREATE TABLE `_pi_first` (`page_id` INT NOT NULL PRIMARY KEY, `sprite_id` INT NOT NULL) ENGINE=InnoDB;
INSERT INTO `_pi_first` (`page_id`, `sprite_id`)
    SELECT ci.`page_id`, SUBSTRING_INDEX(GROUP_CONCAT(f.`sprite_id` ORDER BY f.`item_name`, f.`id`), ',', 1)
      FROM `catalog_items` ci
      JOIN `_pi_pages` s ON s.`id` = ci.`page_id`
      JOIN `furniture` f ON CAST(f.`id` AS CHAR) = ci.`item_id`
      JOIN `_pi_sprite` x ON x.`sprite_id` = f.`sprite_id`
     GROUP BY ci.`page_id`;
UPDATE `catalog_pages` p JOIN `_pi_first` r ON r.`page_id` = p.`id`
   SET p.`icon_image` = 7000000 + r.`sprite_id`;

-- Pages with none: the first sub-page's icon, three levels up.
DROP TABLE IF EXISTS `_pi_child`;
CREATE TABLE `_pi_child` (`parent_id` INT NOT NULL PRIMARY KEY, `icon` INT NOT NULL) ENGINE=InnoDB;
INSERT INTO `_pi_child` (`parent_id`, `icon`)
    SELECT c.`parent_id`, SUBSTRING_INDEX(GROUP_CONCAT(c.`icon_image` ORDER BY c.`order_num`, c.`id`), ',', 1)
      FROM `catalog_pages` c JOIN `_pi_pages` s ON s.`id` = c.`id`
     WHERE c.`page_link` <> 'divider'
     GROUP BY c.`parent_id`;
UPDATE `catalog_pages` p
  JOIN `_pi_pages` s ON s.`id` = p.`id`
  JOIN `_pi_child` k ON k.`parent_id` = p.`id`
   SET p.`icon_image` = k.`icon`
 WHERE NOT EXISTS (SELECT 1 FROM `catalog_items` ci WHERE ci.`page_id` = p.`id`);
